SELECT 
FROM xxl_ai_todo_message AS t
WHERE t.user_id = #{userId}
	AND t.status = 'sent'

		AND t.read_status = #{readStatus}

ORDER BY t.id DESC
LIMIT #{offset}, #{pagesize}

